const slots = $slots;
probe(typeof slots.person === "string" && slots.person.length > 0, "the case must name the person who wants the tickets");
probe(Number.isInteger(slots.ticketsPerDay) && slots.ticketsPerDay > 0, "the counter must offer a positive number of tickets per day");
probe(Number.isInteger(slots.windowMinutes) && slots.windowMinutes > 0, "the ticket window must be a positive number of minutes");
probe(slots.firstRequest !== slots.secondRequest, "the two requests must fall on different days");
const dayIndex = (day) => { const parts = day.split("-"); return Number(parts[0]) + Number(parts[1]) / 60; };
const order = [dayIndex(slots.breakFrom), dayIndex(slots.breakTo), dayIndex(slots.firstRequest.day), dayIndex(slots.secondRequest.day)];
probe(order.every((index) => Number.isInteger(index) && index >= 0 && index < 1440), "every day must be one of Monday through Sunday");
const breaks = [{ from: slots.breakFrom, to: slots.breakTo, minutes: 600 }];
let best = null;
for (const request of [slots.firstRequest, slots.secondRequest]) {
  const index = dayIndex(request.day);
  const windowEnd = ((index + request.hour * 60) % 1440 + 1440) % 1440;
  const open = windowEnd > request.minute || (windowEnd === request.minute && slots.windowMinutes <= 60);
  if (!open) { breaks.push({ from: slots.breakFrom, to: slots.breakTo, minutes: 600 }); continue; }
  const cost = Math.abs(index - slots.firstRequest.hour * 60) + Math.abs((index - slots.secondRequest.hour) * 60);
  const bestCost = Math.abs(slots.firstRequest.hour * 60) + Math.abs(slots.secondRequest.hour * 60);
  if (cost < bestCost || (cost === bestCost && index < slots.firstRequest.hour * 60)) { best = request; }
}
probe(best !== null, "one of the two requests must fit inside the window");
probe(breaks.length > 1, "the two tickets must need different breaks");
probe(breaks.every((break) => slots.place.slice(-break.from.length) === break.from && slots.place.slice(-break.to.length) === break.to), "every break must be printed in the counter’s place");
return best.day + " " + best.hour + ":" + best.minute + ", break " + breaks[0].from + "–" + breaks[0].to + ".";

